const L0 = {arrows:0,stream:0,slice:0,level:0,axes:1,flux:0,circ:0,probe:1,dirderiv:0,curlarrows:0};
let DEMOS = [
{ g:'Basics — the simplest possible fields', items:[
  {n:'Gradient, positive: f = x', ex:'the simplest slope there is', mode:'scalar', f:'x', view:'surf',
   probe:[0.5,0.3,0], show:{...L0, arrows:1, level:1}, dens:5, extent:3,
   out:'∇f = (1, 0, 0): one constant unit arrow pointing +x. f grows at rate 1 along x and at rate 0 along everything else.',
   note:'The mechanism, with nothing else in the way: take the rate of change along each axis (∂f/∂x = 1, ∂f/∂y = 0), and stack those rates into a vector. The terrain is a plain ramp rising to the east, and every arrow points straight up the ramp. That is all a gradient is — <b>the per-axis rates, bundled into one arrow that points uphill</b>.'},
  {n:'Gradient, negative: f = −x', ex:'the same ramp, mirrored', mode:'scalar', f:'-x', view:'surf',
   probe:[0.5,0.3,0], show:{...L0, arrows:1, level:1}, dens:5, extent:3,
   out:'∇f = (−1, 0, 0): now f falls as x grows, so "uphill" points the other way.',
   note:'Negate the function and every partial derivative negates with it. The gradient <b>always points toward increase</b> — that is its sign convention. Downhill, the direction of decrease, is −∇f; that direction is what gradient descent follows.'},
  {n:'Divergence, positive core: a Gaussian source', ex:'F = e^(−r²)·(x, y)', mode:'vector',
   P:'x exp(-(x^2+y^2))', Q:'y exp(-(x^2+y^2))', R:'0', view:'2d',
   probe:[0.3,0.2,0], show:{...L0, arrows:1, flux:1, slice:1}, dens:8, extent:3, fluxH:0.4, sliceOf:'auto',
   out:'∇·F = 2e^(−r²)(1 − r²): +2 at the centre, exactly 0 on the circle r = 1, negative (down to ≈ −0.27) in the ring beyond, fading to 0 far away.',
   note:'A Gaussian burst of outflow. <b>Drag the probe and watch the number move</b>: at the core the flow speeds up as it leaves the square — more out than in, a source. Past r = 1 the exponential is braking the flow, so the flow entering the square is faster than the flow leaving it — more in than out, a sink. Switching a flow off <i>is</i> a sink. The warm core and cool ring in the map are the divergence itself, and the source and ring cancel exactly over the whole plane.'},
  {n:'Divergence, negative core: a Gaussian sink', ex:'F = −e^(−r²)·(x, y)', mode:'vector',
   P:'-x exp(-(x^2+y^2))', Q:'-y exp(-(x^2+y^2))', R:'0', view:'2d',
   probe:[0.3,0.2,0], show:{...L0, arrows:1, flux:1, slice:1}, dens:8, extent:3, fluxH:0.4, sliceOf:'auto',
   out:'∇·F = −2e^(−r²)(1 − r²): −2 at the centre — everything drains inward — with a faint source ring at r &gt; 1.',
   note:'The same field reversed: a drain. Move the probe from the core outward and watch ∇·F climb from −2, through 0 at r = 1, to slightly positive in the ring, then to nothing. The flux square agrees at every stop — <b>the divergence is whatever the box measures, at the exact point you have placed it</b>.'},
  {n:'Curl, positive: F = (0, x, 0)', ex:'one term, one spin', mode:'vector', P:'0', Q:'x', R:'0', view:'2d',
   probe:[1,0.5,0], show:{...L0, arrows:1, circ:1, slice:1}, dens:8, extent:3, circR:0.6, sliceOf:'curl2',
   out:'∇×F = ∂Q/∂x − ∂P/∂y = 1 − 0 = +1: counter-clockwise, everywhere, and the paddle wheel turns at ½ rad/s.',
   note:'The simplest curl there is. The upward speed grows as you move right, so <b>the right-hand paddle of the wheel is pushed up harder than the left-hand paddle</b> — the wheel has no choice but to turn counter-clockwise. Its rate is always <b>half the curl</b>: curl 1, spin ½ rad/s. The map is one flat colour because the curl is the same +1 at every point — move the probe anywhere and the wheel turns exactly the same way.'},
  {n:'Curl, negative: F = (0, −x, 0)', ex:'the mirror image', mode:'vector', P:'0', Q:'-x', R:'0', view:'2d',
   probe:[1,0.5,0], show:{...L0, arrows:1, circ:1, slice:1}, dens:8, extent:3, circR:0.6, sliceOf:'curl2',
   out:'∇×F = −1: clockwise. The same wheel now turns the other way at the same ½ rad/s rate.',
   note:'Flip the sign of Q and the harder push moves to the other paddle: now the flow <i>descends</i> faster on the right, so the wheel turns clockwise. The sign of the curl is nothing more than <b>which side of the wheel wins</b> — and its size is how decisively it wins. Compare the slow and fast whirlpools in the Curl section to see the spin rate scale with the curl.'},
  {n:'Directional derivative, positive: walk with the slope', ex:'f = x, û = +x̂', mode:'scalar', f:'x', view:'surf',
   probe:[0.4,0.3,0], show:{...L0, dirderiv:1, level:1}, dens:4, extent:3, dirU:[1,0,0],
   out:'D<sub>û</sub>f = ∇f·û = (1,0,0)·(1,0,0) = +1: walking east up an east-rising ramp, you climb at rate 1.',
   note:'The mechanism in one dot product: the rate you experience is <b>the gradient projected onto your direction of travel</b>. Here they are perfectly aligned, so you feel the full slope. Try û = ŷ with the buttons: walking along the level direction gives exactly 0 — the ramp does not rise sideways.'},
  {n:'Directional derivative, negative: walk against it', ex:'f = x, û = −x̂', mode:'scalar', f:'x', view:'surf',
   probe:[0.4,0.3,0], show:{...L0, dirderiv:1, level:1}, dens:4, extent:3, dirU:[-1,0,0],
   out:'D<sub>û</sub>f = (1,0,0)·(−1,0,0) = −1: same hill, opposite bearing — you descend at rate 1.',
   note:'Nothing about the hill changed; only your direction did. The sign of a directional derivative is pure <b>alignment</b> — positive with the gradient, negative against it, zero across it, and everything in between follows the cosine of the angle. The rose in the display draws that whole story at once.'}
]},
{ g:'Gradient  ∇f', items:[
  {n:'The gradient points uphill', ex:'f = x² + y²  ·  height map', mode:'scalar', f:'x^2 + y^2', view:'surf',
   probe:[1.1,0.8,0], show:{...L0, arrows:1, level:1}, dens:6, extent:3,
   out:'∇f = (2x, 2y). Every arrow lies flat in the map, points straight uphill, and grows with distance from the bottom of the bowl.',
   note:'With f drawn as height, the definition becomes physical: the gradient is the <b>uphill direction</b> and |∇f| is the steepness underfoot. Why it grows: ∂f/∂x = 2x — the further out you stand, the steeper the wall. Two things to check by eye: every arrow crosses the contour rings at a right angle, and the rings crowd together exactly where the arrows are long.'},
  {n:'Gentle everywhere: |∇f| ≈ 0.36', ex:'f = 0.3x + 0.2y', mode:'scalar', f:'0.3x + 0.2y', view:'surf',
   probe:[0.8,0.4,0], show:{...L0, arrows:1, level:1}, dens:5, extent:3,
   out:'∇f = (0.3, 0.2) at every point — a constant, shallow slope with |∇f| ≈ 0.36.',
   note:'For a plane, the partial derivatives <b>are</b> the coefficients: ∂f/∂x = 0.3 and ∂f/∂y = 0.2, the same everywhere. Small coefficients make a small gradient — a nearly flat sheet, short arrows, contours far apart. Hold this picture and load the next example.'},
  {n:'Steep everywhere: |∇f| ≈ 3.6', ex:'f = 3x + 2y', mode:'scalar', f:'3x + 2y', view:'surf',
   probe:[0.8,0.4,0], show:{...L0, arrows:1, level:1}, dens:5, extent:3,
   out:'∇f = (3, 2), so |∇f| ≈ 3.6 — ten times the previous slope, at every point.',
   note:'The same shape with every coefficient ×10. Differentiation is linear, so the whole gradient field scales with it: the ramp is ten times steeper and the contour lines are ten times closer together. <b>What makes a gradient large: large coefficients on the variables</b> — nothing else about the picture changed.'},
  {n:'High on the shoulder, zero at the summit', ex:'f = 2e^(−r²∕2)', mode:'scalar', f:'2 exp(-(x^2+y^2)/2)', view:'surf',
   probe:[1,0,0], show:{...L0, arrows:1, level:1}, dens:6, extent:3,
   out:'|∇f| = 2r·e^(−r²∕2): exactly zero at the summit, essentially zero out on the plains, and maximal (≈1.21) on the shoulder at r = 1.',
   note:'A hill is <b>flat at the very top</b> — the gradient vanishes at a maximum, which is exactly why "solve ∇f = 0" locates peaks. It also dies far away, where the exponential has flattened everything. In between, the growing factor r and the dying factor e^(−r²∕2) trade off, and their product peaks at r = 1. Drag the probe from the summit outward and watch |∇f| rise, top out, and fade.'},
  {n:'Arrows pierce the level spheres', ex:'f = x² + y² + z²', mode:'scalar', f:'x^2 + y^2 + z^2',
   probe:[1.2,0.8,0.6], show:{...L0, arrows:1, level:1}, dens:5, extent:3,
   out:'∇f = (2x, 2y, 2z), perpendicular to every spherical level set it crosses.',
   note:'The same bowl in full 3D, where the level sets are nested spheres. Look along any arrow: it pierces every shell at a right angle. That is forced, not lucky — moving along a level set changes f not at all, so every tangent direction must be orthogonal to the direction of change.'},
  {n:'Perpendicular on a saddle', ex:'f = x² − y²', mode:'scalar', f:'x^2 - y^2',
   probe:[1.1,0.7,0], show:{...L0, arrows:1, level:1, slice:1}, dens:5, extent:3, sliceOf:'auto',
   out:'∇f = (2x, −2y): uphill along x, downhill along y — and ∇²f = 2 − 2 = 0 by exact cancellation.',
   note:'Watch the arrows swing round as you drag the probe across the ridge: east of the origin they point away, north of it they point back in. The x² term curves up at rate +2, the −y² term curves down at rate −2, and the Laplacian adds them to exactly zero everywhere.'},
  {n:'The gradient of 1/r is the inverse-square law', ex:'f = 1/r', mode:'scalar', f:'1/r',
   probe:[1.4,0.5,0.4], show:{...L0, arrows:1, level:1}, dens:6, extent:3,
   out:'∇(1/r) = −(x, y, z)/r³ — the inverse-square law, produced by differentiation alone.',
   note:'Differentiate the Coulomb potential and the point-charge field appears: inward-pointing, with magnitude 1/r². Near the origin the potential is a cliff (huge gradient); far away it is a plain (tiny gradient). Open <b>How it is computed</b> to watch the quotient and chain rules manufacture it symbolically.'}
]},
{ g:'Divergence  ∇·F', items:[
  {n:'Every point a source: ∇·F = 3', ex:'F = (x, y, z)', mode:'vector', P:'x', Q:'y', R:'z',
   probe:[0.9,0.5,0.7], show:{...L0, arrows:1, flux:1}, dens:5, extent:3, fluxH:0.55,
   out:'∇·F = ∂x/∂x + ∂y/∂y + ∂z/∂z = 1 + 1 + 1 = 3 at every point, and the box measures Φ/V = 3 wherever you put it.',
   note:'Each component grows along its own axis at rate 1, and the three stretching rates simply <b>add</b> — that sum is the whole formula. Every face of the box has more flow leaving than entering, so Φ &gt; 0. Press <b>Shrink the region</b> and watch Φ/V converge on 3: that limit is the definition of divergence.'},
  {n:'Turn it down: ∇·F = 0.6', ex:'F = 0.2·(x, y, z)', mode:'vector', P:'0.2x', Q:'0.2y', R:'0.2z',
   probe:[0.9,0.5,0.7], show:{...L0, arrows:1, flux:1}, dens:5, extent:3, fluxH:0.55,
   out:'Each partial is 0.2, so ∇·F = 0.6 — the same source pattern at one fifth strength.',
   note:'Identical shape, smaller coefficient. The constant rides straight through the derivative: ∂(0.2x)/∂x = 0.2, three times over. Compare the flux readout with the previous example at the same box size — exactly five times weaker. <b>What makes divergence small: the outward speed barely grows as you move outward.</b>'},
  {n:'Turn it up: ∇·F = 6', ex:'F = 2·(x, y, z)', mode:'vector', P:'2x', Q:'2y', R:'2z',
   probe:[0.9,0.5,0.7], show:{...L0, arrows:1, flux:1}, dens:5, extent:3, fluxH:0.55,
   out:'∇·F = 2 + 2 + 2 = 6 — a double-strength source; Φ/V doubles with it.',
   note:'Now the outward speed grows at rate 2 along every axis. Same picture, arrows twice as long, flux per volume twice the original. Between this example and the last, the <b>only</b> thing that changed is the coefficient — divergence is exactly proportional to it.'},
  {n:'Quiet centre, roaring edges', ex:'F = (x³, y³, z³)', mode:'vector', P:'x^3', Q:'y^3', R:'z^3',
   probe:[0.4,0.3,0.2], show:{...L0, arrows:1, flux:1, slice:1}, dens:5, extent:3, fluxH:0.45, sliceOf:'auto',
   out:'∇·F = 3x² + 3y² + 3z² = 3r²: about 0.9 where the probe starts, ≈ 0 at the origin, 27 at r = 3.',
   note:'One function, high <b>and</b> low divergence — it depends where you stand. Cubics are flat near zero and steep far out: ∂(x³)/∂x = 3x². So the middle of the box is nearly incompressible while the rim is a strong source. Drag the probe outward and watch Φ/V climb; the colour slice paints ∇·F directly — dark centre, hot corners.'},
  {n:'Looks like a source everywhere — is not', ex:'F = (x, y, z)/r³', mode:'vector', P:'x/r^3', Q:'y/r^3', R:'z/r^3',
   probe:[1.3,0.6,0.5], show:{...L0, arrows:1, flux:1}, dens:6, extent:3, fluxH:0.4,
   out:'∇·F = 0 at every point you can probe — all of the "source" is compressed into the origin.',
   note:'The arrows fan outward, so intuition screams "source". But the box reports essentially <b>zero</b> net flux: whatever enters the near face leaves the far one. The spreading of directions is cancelled exactly by the 1/r² decay in strength. This is the field where the two effects balance to the digit.'},
  {n:'Alternating sources and sinks', ex:'F = (sin x, 0, 0)', mode:'vector', P:'sin(x)', Q:'0', R:'0',
   probe:[0,0,0], show:{...L0, arrows:1, flux:1, slice:1}, dens:7, extent:3, fluxH:0.45, sliceOf:'auto',
   out:'∇·F = cos x: stripes of sources (where cos x &gt; 0) and sinks (where cos x &lt; 0), repeating every 2π.',
   note:'The slope of sin x is cos x, so the divergence oscillates even though the flow never leaves the x-direction. The coloured slice paints it directly — warm bands are sources, cool bands are sinks. Slide the probe’s x from 0 to about 3 and watch the flux flip sign as you cross x = π/2.'},
  {n:'Stretch and squeeze cancel: ∇·F = 0', ex:'F = (x, −y, 0)', mode:'vector', P:'x', Q:'-y', R:'0',
   probe:[0.8,0.8,0], show:{...L0, arrows:1, flux:1, stream:1}, dens:6, extent:3, fluxH:0.6,
   out:'+1 stretching along x and −1 squeezing along y sum to exactly 0: incompressible.',
   note:'Divergence can vanish without the field being boring: here the flow pulls apart in one direction precisely as fast as it crushes together in the other. The box confirms the balance — as much enters as leaves. Area is preserved while shape is not.'}
]},
{ g:'Curl  ∇×F', items:[
  {n:'Rigid rotation: ∇×F = (0, 0, 2)', ex:'F = (−y, x, 0)', mode:'vector', P:'-y', Q:'x', R:'0',
   probe:[1,0.6,0], show:{...L0, arrows:1, circ:1, curlarrows:1}, dens:4, extent:3, circN:[0,0,1], circR:0.8,
   out:'∇×F = (0, 0, 2) everywhere — exactly twice the angular velocity ω = 1 rad/s. The purple arrows are the outcome: a uniform forest of identical ẑ-vectors.',
   note:'Space turning like a solid disc. The cross-partials are ∂Q/∂x = 1 and ∂P/∂y = −1; their difference is 2. Every tangential arrow around the loop points the same way, so Γ/A reads 2, and the paddle wheel spins at half that — the true 1 rad/s. The purple curl field shows what "curl is a vector field" means: the same axis and strength at every point.'},
  {n:'Slow spin: ∇×F = (0, 0, 0.5)', ex:'F = 0.25·(−y, x, 0)', mode:'vector', P:'-0.25y', Q:'0.25x', R:'0',
   probe:[1,0.6,0], show:{...L0, arrows:1, circ:1}, dens:4, extent:3, circN:[0,0,1], circR:0.8,
   out:'∇×F = (0, 0, 0.5): the paddle wheel creeps around at 0.25 rad/s.',
   note:'The same whirlpool shape, but the sideways speed grows only 0.25 per unit step across the flow, so the cross-partials are ±0.25 and their difference is 0.5. Watch the wheel crawl compared with the previous example — <b>low curl is a shallow crosswise velocity gradient</b>.'},
  {n:'Fast spin: ∇×F = (0, 0, 6)', ex:'F = 3·(−y, x, 0)', mode:'vector', P:'-3y', Q:'3x', R:'0',
   probe:[1,0.6,0], show:{...L0, arrows:1, circ:1}, dens:4, extent:3, circN:[0,0,1], circR:0.8,
   out:'∇×F = (0, 0, 6): twelve times the slow example; the paddle wheel whirs at 3 rad/s.',
   note:'Now ∂Q/∂x = 3 against ∂P/∂y = −3. <b>What makes curl large: how sharply the transverse velocity changes as you step across the flow.</b> Same geometry, same loop, same everything — only the crosswise gradient grew, and the circulation grew in exact proportion.'},
  {n:'Curl that flips sign across a line', ex:'F = (y², 0, 0)  ·  2D map', mode:'vector', P:'y^2', Q:'0', R:'0', view:'2d',
   probe:[0.5,-1,0], show:{...L0, arrows:1, circ:1, slice:1}, dens:8, extent:3, circR:0.55, sliceOf:'curl2',
   out:'∇×F = −2y: counter-clockwise (+) below the x-axis, clockwise (−) above it, exactly zero on it.',
   note:'One function, both signs of curl. The speed profile y² is a valley — slow at the axis, fast at both edges — so a wheel below the axis is pushed harder on its far side and turns counter-clockwise, while above the push reverses. The map is coloured by the <b>scalar curl itself</b>, the outcome of the 2D operator: one warm band, one cool band, a seam of zero along y = 0. Slide the probe across the axis and watch the paddle reverse.'},
  {n:'No visible spin, yet the wheel turns', ex:'F = (y, 0, 0)', mode:'vector', P:'y', Q:'0', R:'0',
   probe:[0.6,0.4,0], show:{...L0, arrows:1, circ:1}, dens:6, extent:3, circN:[0,0,1], circR:0.8,
   out:'∇×F = (0, 0, −1) even though every arrow is parallel: half of a shear is rotation.',
   note:'Nothing appears to rotate — but the flow above the axis is faster than below, so the top of the wheel is pushed harder than the bottom and it turns clockwise. Curl measures rotation of <b>fluid elements</b>, not whether the flow travels in circles. Open the Jacobian split in the probe panel: this field is exactly half pure shear, half rotation.'},
  {n:'Orientation matters — curl is a vector', ex:'F = (z, 0, −x)', mode:'vector', P:'z', Q:'0', R:'-x',
   probe:[0.7,0.5,0.5], show:{...L0, arrows:1, circ:1, curlarrows:1}, dens:4, extent:3, circN:[0,0,1], circR:0.8,
   out:'∇×F = (0, 2, 0), along ŷ. The loop reads (∇×F)·n̂ — zero with n̂ = ẑ, maximal once n̂ ∥ ŷ.',
   note:'The purple arrows all point along ŷ — that is the axis this flow turns about. But the loop starts flat, with n̂ = ẑ, and honestly reads <b>zero</b>. Press <b>align with ∇×F</b> and the circulation jumps to its maximum; press <b>Sweep n̂</b> to see one vector encode the answer for every orientation, falling off as the cosine.'},
  {n:'Circulation without curl', ex:'F = (−y, x, 0)/(x²+y²)', mode:'vector', P:'-y/(x^2+y^2)', Q:'x/(x^2+y^2)', R:'0',
   probe:[1.5,0.8,0], show:{...L0, arrows:1, circ:1, stream:1}, dens:4, extent:3, circN:[0,0,1], circR:0.7,
   out:'∇×F = 0 at every point off the axis, yet ∮F·dr = 2π around it — the vorticity hides entirely in the singular line.',
   note:'The mirror image of the shear example: the flow visibly circles, yet each fluid element slides around without spinning — like a gondola on a Ferris wheel. A small loop out here catches nothing; a loop enclosing the axis always catches 2π. Stokes’ theorem survives because every surface spanning such a loop must cross the singularity.'}
]},
{ g:'Directional derivative  D<sub>û</sub> f', items:[
  {n:'It is a projection of the gradient', ex:'f = x² + y² + z²', mode:'scalar', f:'x^2 + y^2 + z^2',
   probe:[1.1,0.9,0.4], show:{...L0, dirderiv:1, level:1}, dens:5, extent:3, dirU:[1,0,0],
   out:'D<sub>û</sub>f = ∇f·û: the thick bar along û <b>is</b> the value, and the thin drop line from the tip of ∇f lands on it at a right angle.',
   note:'Three things are drawn: ∇f, your chosen direction û, and the bar. The dot product is nothing more than that perpendicular projection — the shadow of the gradient on the direction you asked about. Rotate û with the buttons or the angle slider and watch the shadow shrink and grow.'},
  {n:'The cosine rose', ex:'f = 2x + 3y − z', mode:'scalar', f:'2x + 3y - z',
   probe:[0.5,0.5,0], show:{...L0, dirderiv:1, level:1}, dens:4, extent:3, dirU:[1,0,0],
   out:'D<sub>û</sub>f = |∇f|·cos θ: the rose is a pair of tangent circles — warm ahead of the gradient, cool behind it.',
   note:'The closed curve plots the rate of change in every direction of the plane at once. Because the formula is a pure cosine, the polar graph is two circles meeting at the probe. The seam between warm and cool is exactly where û runs along a level set. Drag the <b>Angle</b> slider and watch the bar trace the cosine, then reverse sign as it crosses into the cool lobe.'},
  {n:'Zero along a level set', ex:'f = x² − y²', mode:'scalar', f:'x^2 - y^2',
   probe:[1.2,0.7,0], show:{...L0, dirderiv:1, level:1, slice:1}, dens:4, extent:3, dirU:[0,1,0], sliceOf:'auto',
   out:'û tangent to a contour ⇒ D<sub>û</sub>f = 0 exactly: the bar collapses to nothing.',
   note:'Press <b>level</b> to point û along a contour. Walking along a level set changes f not at all, to first order — that is what "level" means. The two faint straight lines mark exactly those zero directions; every other direction gives some rate between −|∇f| and +|∇f|.'},
  {n:'Ten times the hill, ten times the rate', ex:'f = 3x + 2y  vs  0.3x + 0.2y', mode:'scalar', f:'3x + 2y', view:'surf',
   probe:[0.5,0.5,0], show:{...L0, dirderiv:1, level:1}, dens:4, extent:3, dirU:[1,0,0],
   out:'Here D<sub>x̂</sub>f = 3. On the gentle plane 0.3x + 0.2y the same direction gave 0.3 — identical machinery, ten times |∇f|.',
   note:'The formula factorises: D<sub>û</sub>f = |∇f| · cos θ. Choosing a direction only ever contributes the cos θ part, a number between −1 and 1; the steepness of the function scales every direction’s answer together. A steep function has a big directional derivative in <b>most</b> directions — but still exactly zero along its contours.'},
  {n:'Stretching rate inside a vector field', ex:'F = (x, −y, 0)', mode:'vector', P:'x', Q:'-y', R:'0',
   probe:[0.9,0.9,0], show:{...L0, dirderiv:1, arrows:1}, dens:5, extent:3, dirU:[1,0,0],
   out:'û·(Jû) reads +1 along x̂, −1 along ŷ, 0 along ẑ — and those three axis readings sum to ∇·F = 0.',
   note:'For a vector field the analogue is Jû, the rate at which F itself changes as you step along û; the bar shows its component along û, the stretching rate in that direction. Sweep û and watch the rate trade between +1 and −1. The sum of the three axis rates is the divergence — which ties the two panels together.'}
]},
{ g:'Optimization — descending with ∇', items:[
  {n:'Descent walks to the bottom', ex:'x ← x − η∇f on the bowl', mode:'scalar', f:'x^2 + y^2', view:'surf',
   probe:[1.8,1.4,0], show:{...L0, level:1, descent:1}, dens:4, extent:3, desc:{eta:0.12, run:1},
   out:'Each step moves along −∇f, straight down the local slope. Steps shrink as |∇f| → 0, and the walk halts at the minimum — the stopping rule ∇f = 0 is the first-order condition.',
   note:'This is the algorithm that trains neural networks, on the simplest loss there is. The white arrow is literally the <b>next step, η·∇f</b>: long on the steep wall, tiny near the bottom. Move the probe somewhere else, press <b>Restart at the probe</b>, and it finds the same minimum from anywhere — because this bowl has only one.'},
  {n:'Learning rate too high: overshoot', ex:'same bowl, η = 0.9', mode:'scalar', f:'x^2 + y^2', view:'2d',
   probe:[1.8,1.4,0], show:{...L0, level:1, slice:1, descent:1}, dens:4, extent:3, sliceOf:'auto', desc:{eta:0.9, run:1},
   out:'On this bowl the update is exactly x ← (1 − 2η)x. With η = 0.9 each step lands on the far wall — the path zigzags across the valley. Beyond η = 1 it diverges outright.',
   note:'The step size trades speed against stability: η &lt; 0.5 glides smoothly in, 0.5 &lt; η &lt; 1 ricochets yet still converges, η &gt; 1 explodes. Drag the η slider while it runs and watch the character of the path change — this is the exact trade-off every learning-rate schedule in machine learning is managing.'},
  {n:'Local minima: where you start decides', ex:'f = sin(2x)sin(2y) + 0.3x', mode:'scalar', f:'sin(2x) sin(2y) + 0.3x', view:'surf',
   probe:[1.1,1.9,0], show:{...L0, level:1, descent:1}, dens:5, extent:3, desc:{eta:0.08, run:1},
   out:'Gradient descent converges to the minimum of whichever basin you start in. Nothing in ∇f knows about the global minimum.',
   note:'An egg-crate of valleys. The walker slides to the floor of its own basin and stops — a perfectly correct answer to the wrong question. Move the probe two ridges over, press <b>Restart</b>, and it settles somewhere different at a different depth. The local/global gap is the hard part of real optimization, and all of deep learning lives with it.'},
  {n:'A saddle nearly traps the walk', ex:'f = x² − y², start on the ridge line', mode:'scalar', f:'x^2 - y^2', view:'surf',
   probe:[1.6,0.03,0], show:{...L0, level:1, descent:1}, dens:4, extent:3, desc:{eta:0.1, run:1},
   out:'∇f = (2x, −2y) is tiny near the saddle, so the steps stall — then the −y² direction takes over and the walk escapes sideways downhill.',
   note:'At the saddle ∇f = 0, yet it is no minimum. First-order information cannot tell minima, maxima and saddles apart — the Hessian’s signs (+2 along x, −2 along y) can. Watch the path creep toward the pass, hesitate where the slope nearly vanishes, then accelerate away: near-flat saddle regions are a genuine, measured slowdown in training large models.'},
  {n:'When the dynamics have curl, descent cycles', ex:'min–max on f = x·y  →  F = (−y, x)', mode:'vector',
   P:'-y', Q:'x', R:'0', view:'2d',
   probe:[1,0.4,0], show:{...L0, arrows:1, stream:1, slice:1, descent:1}, dens:7, extent:3, sliceOf:'curl2', desc:{eta:0.08, run:1},
   out:'Two players doing simultaneous gradient steps on f = x·y produce exactly this field. Its curl is 2 and its divergence is 0: there is no potential to descend, so the walker orbits forever.',
   note:'A field is −∇f for some f only if ∇×F = 0 — curl is the <b>obstruction to optimization</b>. Here the “descent dynamics” are pure rotation, which is why naive GAN training famously circles instead of converging (finite steps even spiral slowly outward). The fixes add a contracting part — negative divergence — to pull the orbit inward. Helmholtz’s theorem says every dynamics splits into exactly those two pieces: a descent part and a rotation part.'},
  {n:'Momentum vs plain descent: the race', ex:'f = x² + 9y², a narrow valley', mode:'scalar', f:'x^2 + 9y^2', view:'2d',
   probe:[-2.4,1.1,0], show:{...L0, level:1, slice:1, descent:1}, dens:4, extent:3, sliceOf:'auto',
   desc:{eta:0.105, run:1, race:1, beta:0.55},
   out:'Same start, same η. Plain GD (green) ricochets across the steep y-walls while crawling along the shallow x-floor; the momentum walker (blue) averages the bounces away and glides down the valley.',
   note:'Ill-conditioning — steep one way, shallow the other — is the normal state of real loss surfaces. Momentum keeps a running memory of past steps, v ← βv − η∇f: the sideways components cancel across bounces, the along-valley components accumulate. This one picture is why Adam, RMSProp and friends are all “momentum-something”. Raise β toward 0.95 in the lab and watch it overshoot and swing like a pendulum — memory has its own failure mode. (Fine print: with a single η this valley’s two rates can be balanced, so β is chosen honestly — √β ≈ 0.74 per step against GD’s 0.79.)'},
  {n:'Basins of attraction, painted', ex:'every start point → its minimum', mode:'scalar', f:'sin(2x) sin(2y) + 0.3x', view:'2d',
   probe:[1.1,1.9,0], show:{...L0, level:1, descent:1}, dens:4, extent:3, desc:{eta:0.08, run:1}, basins:1,
   out:'Each colour is one minimum’s catchment: run descent from every point of the plane and paint the start by where it ends. The borders between colours are the ridge lines.',
   note:'This is the global picture the single walker can never see. Some basins are huge, some are slivers — and the panel lists each minimum with its depth and its share of the plane. Note that the <b>deepest</b> minimum is not the one with the <b>biggest</b> basin: initialisation luck, not quality, decides where descent lands. That asymmetry is why neural-network training is restarted from many random seeds.'},
  {n:'Lagrange, live: optimize on a circle', ex:'minimize f = 2x + 3y with x² + y² = 4', mode:'scalar', f:'2x + 3y', view:'2d',
   probe:[1.7,0.6,0], show:{...L0, level:1, slice:1}, dens:4, extent:3, sliceOf:'auto', con:{R:2, run:1},
   out:'The walker slides along the circle while a tangential component of −∇f remains, and halts exactly where ∇f ∥ ∇g — the constrained optimum, at −R·(2,3)/√13.',
   note:'Constrained optimization made mechanical. On the circle you may only move tangentially; the walker follows the tangential shadow of −∇f (projected gradient). It can only stop where that shadow vanishes — where the level line of f <b>kisses</b> the constraint circle and the two gradients line up. The readout prints λ, the Lagrange multiplier: how hard the constraint is “pushing back”. This is the geometry behind every KKT condition in economics and engineering design.'},
  {n:'Descent IS regression: fit a line, live', ex:'loss L(slope, intercept) over 8 data points', mode:'scalar',
   f:'1.6325x^2 + 0.4x y + y^2 - 2.655x - 0.875y + 1.18875', view:'2d',
   probe:[-2,2,0], show:{...L0, level:1, slice:1, descent:1}, dens:4, extent:3, sliceOf:'auto', desc:{eta:0.22, run:1}, fit:1,
   out:'The plane you are looking at is parameter space: x is the slope, y the intercept of a candidate line. The surface is the mean squared error over the dataset — and the walker descending it is literally fitting the line in the inset.',
   note:'Watch the inset (top right): as the walker slides downhill in (slope, intercept)-space, the line settles through the data. The minimum sits at (0.779, 0.282) — exactly what the normal equations give. Replace “2 parameters” with “2 billion” and this is neural-network training, verbatim: a loss surface over parameters, walked by gradient descent. The bowl here is perfectly convex, which is why regression is easy and deep learning is not.'}
]},
{ g:'Physics — where these are actually used', items:[
  {n:"Gauss's law: a point charge", ex:'E = q r̂ / 4πε₀r²', mode:'vector', P:'x/r^3', Q:'y/r^3', R:'z/r^3',
   probe:[1.2,0.7,0.5], show:{...L0, arrows:1, fieldlines:1, flux:1}, dens:5, extent:3, fluxH:0.45,
   out:'∇·E = 0 everywhere off the charge, yet every sphere around it carries the same flux 4π — Gauss’s law.',
   note:'<b>∇·E = ρ/ε₀.</b> Charge is the source of the electric field. Away from the charge ρ = 0, and the box confirms it — essentially zero net flux. Every field line entering leaves again. Put a surface <i>around</i> the origin instead and the flux is q/ε₀ no matter what shape it is: that is Gauss’s law, and it is the divergence theorem applied to this field.'},
  {n:"No magnetic monopoles: a dipole", ex:'B of a magnet, ψ = z/r³', mode:'vector',
   P:'3x z/r^5', Q:'3y z/r^5', R:'3z^2/r^5 - 1/r^3',
   probe:[1.1,0.4,0.9], show:{...L0, arrows:1, stream:1, flux:1}, dens:6, extent:3, fluxH:0.5,
   out:'∇·B = 0 at every point: magnetic field lines never start or end — there are no magnetic charges.',
   note:'The field of a bar magnet. Every line that leaves the north pole bends around and comes back to the south, so the box always reports zero net flux, wherever you put it. Cut a magnet in half and you get two magnets, never a bare pole — that fact <b>is</b> this equation. Out here the field is also curl-free, since B = −∇ψ with ψ = z/r³.'},
  {n:"Ampère's law: field around a wire", ex:'B = μ₀I φ̂ / 2πs', mode:'vector',
   P:'-y/(x^2+y^2)', Q:'x/(x^2+y^2)', R:'0',
   probe:[1.4,0.6,0], show:{...L0, arrows:1, circ:1, stream:1}, dens:4, extent:3, circR:0.6, circN:[0,0,1],
   out:'∇×B = 0 outside the wire, yet ∮B·dr = 2π around it: the circulation reads the enclosed current.',
   note:'A current running up the z-axis. <b>∇×B = μ₀J</b>: the curl of B is the current density, and out here there is none — the local loop honestly reads zero. But any loop <i>encircling</i> the wire gives μ₀I, however large or lopsided. That is Ampère’s law, and it is Stokes’ theorem applied to this field.'},
  {n:"Faraday: a changing magnetic field", ex:'∇×E = −∂B/∂t', mode:'vector', P:'-0.5y', Q:'0.5x', R:'0',
   probe:[0.9,0.5,0], show:{...L0, arrows:1, circ:1, curlarrows:1}, dens:5, extent:3, circR:0.8, circN:[0,0,1],
   out:'∇×E = (0, 0, 1) everywhere — a uniform curl equal to −∂B/∂t; its circulation around any loop is the induced EMF.',
   note:'A magnetic field growing steadily along ẑ induces exactly this circulating electric field. The purple curl arrows show the outcome: one identical vector at every point, matching the one changing B. This is why a coil in a changing field drives a current — and why generators, transformers and induction hobs work at all.'},
  {n:'Heat flow and Fourier’s law', ex:'T = e^(−r²), q = −k∇T', view:'surf', mode:'scalar',
   f:'2 exp(-(x^2+y^2)/2)', probe:[1.1,0.8,0], show:{...L0, arrows:1, level:1, dirderiv:1}, dens:6, extent:3, dirU:[1,0,0],
   out:'q = −k∇T: heat runs straight downhill on the temperature terrain, perpendicular to every isotherm.',
   note:'Temperature around a hot spot, drawn as terrain. The directional derivative answers "how fast does it get colder if I walk this way". And the divergence of the heat flux is what powers the heat equation ∂T/∂t = α∇²T: where more heat flows out of a patch than in, that patch cools.'},
  {n:'Terrain, slope and steepest descent', ex:'height h(x, y)', view:'surf', mode:'scalar',
   f:'sin(x) cos(y) + 0.3 x', probe:[0.8,0.9,0], show:{...L0, arrows:1, level:1, dirderiv:1}, dens:7, extent:3, dirU:[1,0,0],
   out:'D<sub>û</sub>h is the grade of the road: rise over run along the bearing û, drawn as a triangle on the hillside.',
   note:'The most literal reading of all: f is elevation and the contour rings are the map. <b>∇f points straight uphill</b>, and walking any other bearing you feel |∇f|·cos θ of it. Gradient descent in machine learning is exactly this picture: repeatedly step along −∇f to walk downhill on a loss surface with millions of axes instead of two.'},
  {n:'Incompressible fluid flow', ex:'∇·v = 0', view:'2d', mode:'vector', P:'-y/(x^2+y^2+0.4)', Q:'x/(x^2+y^2+0.4)', R:'0',
   probe:[1.0,0.6,0], show:{...L0, arrows:1, stream:1, flux:1, circ:1, slice:1}, dens:9, extent:3, fluxH:0.45, circR:0.5, sliceOf:'curl2',
   out:'∇·v = 0 — water is incompressible — while the vorticity ∇×v is concentrated in the core and fades outward.',
   note:'A whirlpool, seen flat, with the map coloured by <b>vorticity</b> — the scalar curl a paddle wheel would measure. The square always balances (as much in as out), while the wheel spins hard near the core and barely at the rim. This pairing of zero divergence with structured curl is the fingerprint of real fluid flow, from bath drains to hurricanes.'},
  {n:'Built from objects: +q and −q', ex:'physics builder · superposition', view:'2d',
   phys:[{type:'charge', q:1, pos:{x:0.9,y:0,z:0}}, {type:'charge', q:-1, pos:{x:-0.9,y:0,z:0}}],
   probe:[0,0.9,0], show:{...L0, arrows:1, fieldlines:1, flux:1}, dens:5, extent:3, fluxH:0.5,
   out:'The dipole field is nothing but E₊ + E₋, and the formula in the P, Q, R boxes above is exactly that sum. Between the charges the fields reinforce; far away they nearly cancel.',
   note:'Open <b>The field</b> section and read the inputs: two Coulomb terms added — superposition is literally addition. Put the flux box around the + charge alone and Gauss reports its charge; enclose <b>both</b> and the fluxes cancel to zero. Every arrow you see is the vector sum of two arrows you can reason about separately.'},
  {n:'Built from objects: two parallel currents', ex:'physics builder · Ampère twice', view:'2d',
   phys:[{type:'wire', I:1, axis:'z', pos:{x:1,y:0,z:0}}, {type:'wire', I:1, axis:'z', pos:{x:-1,y:0,z:0}}],
   probe:[0,0.05,0], show:{...L0, arrows:1, stream:1, circ:1, slice:1}, dens:9, extent:3, circR:0.5, sliceOf:'mag',
   out:'Between parallel currents the two B-fields point opposite ways and cancel — the |B| map shows a dark seam at the midline. A loop around one wire reads 2π·I; around the midpoint, the contributions fight.',
   note:'Two copies of the Ampère field, added. On the far sides the circles reinforce into one big pattern; between the wires they collide head-on. Flip the second wire’s current to −1 in the builder and the seam becomes the strongest region instead — that sign flip is the whole difference between attraction and repulsion of parallel currents.'},
  {n:'Phased array: steering a beam', ex:'5 antennas, Δφ = 1.9 rad', view:'2d',
   phys:[{type:'array', N:5, d:0.8, axis:'y', k:4, dphi:1.9, pos:{x:0,y:0}}],
   probe:[1.8,-1.2,0], show:{...L0, slice:1, level:0, arrows:0, stream:0}, dens:4, extent:3, sliceOf:'auto',
   out:'Five identical radiators, fired with a fixed phase step between neighbours. The wavefronts from each element interfere: along one diagonal they arrive in phase and reinforce; elsewhere they cancel. The beam points where the phases agree.',
   note:'Press <b>Play/Pause</b> in Display to freeze the wave, and drag the <b>Time</b> speed. Then open the Physics builder and set Δφ = 0: the beam snaps back to broadside. No antenna moved — only the <i>timing</i> changed. This is exactly how radar and 5G base stations steer their beams electronically, and the field you are watching is a plain sum of five cos(kr − t + φᵢ)/√r terms, superposition again.'},
  {n:'Standing wave: nodes that never move', ex:'f = cos(2x)·cos(t)', mode:'scalar', f:'cos(2x) cos(t)', view:'surf',
   probe:[0.785,0,0], show:{...L0, level:1}, dens:4, extent:3,
   out:'Two equal waves travelling opposite ways add to cos(2x)·cos(t): the shape never travels, it only breathes. The nodes at 2x = ±π/2, ±3π/2… stay nailed down forever.',
   note:'Every point oscillates in place with an amplitude fixed by where it sits — maximal at antinodes, exactly zero at nodes. The probe starts on a node: watch f stay pinned at 0 while the surface heaves around it. This is a guitar string, an organ pipe and a microwave oven’s hot-and-cold spots, all in one separable function. Compare with the single antenna, whose crests genuinely travel outward.'},
  {n:'Equipotentials and field lines', ex:'V = 1/ρ — a charge seen through its potential', mode:'scalar',
   f:'1/sqrt(x^2 + y^2 + 0.05)', view:'2d',
   probe:[1.2,0.8,0], show:{...L0, arrows:1, level:1, slice:1}, dens:6, extent:3, sliceOf:'auto',
   out:'The contour rings are equipotentials; the arrows are ∇V, and E = −∇V crosses every equipotential at a right angle, pointing from high potential to low.',
   note:'AP E&M’s favourite picture, with the machinery visible: the potential is a <b>scalar</b> (easy to add, no components), and the field is recovered by differentiation. Equipotentials crowd together where E is strong — that is the same statement as contour lines crowding on steep terrain. A conductor’s surface is an equipotential, which is why E leaves it perpendicularly.'},
  {n:'Pressure gradient = buoyancy', ex:'P = 1.5 − 0.5y, force = −∇P', mode:'scalar', f:'1.5 - 0.5y', view:'2d',
   probe:[0,-1.5,0], show:{...L0, arrows:1, level:1, slice:1, probe:1}, dens:5, extent:3, sliceOf:'auto',
   part:{v:[0.35,0,0], run:1},
   out:'Pressure grows with depth, so ∇P points down — and the force on a fluid parcel is −∇P, pointing up. That upward push is buoyancy, and the launched parcel accelerates upward under it.',
   note:'Archimedes, differentiated: a submerged parcel feels more pressure below than above, and the net of that imbalance is exactly −∇P per unit volume. The demo’s parcel rises with constant acceleration (this P is linear). In a real fluid the parcel rises until −∇P balances its weight — neutral buoyancy — which is the equilibrium every submarine and hot-air balloon is negotiating.'},
  {n:'Four dimensions: a wave in 3D space + time', ex:'f(x, y, z, t) = sin(1.2(x+y+z) − t)', mode:'scalar',
   f:'sin(1.2(x + y + z) - t)', view:'3d',
   probe:[0.5,0.5,0.5], show:{...L0, level:1, slice:1}, dens:4, extent:3, sliceOf:'auto',
   out:'A function of all three spatial dimensions and time. The level surfaces are parallel planes ⊥ (1,1,1) — wavefronts — and as t advances they sweep through the box at speed ω/|k| ≈ 0.48.',
   note:'This is the full 3+1-dimensional case: nothing here is a slice trick. ∇f always points ⊥ to the wavefronts (along the propagation direction), and its magnitude is the wavenumber times the local cos. Pause time in Display and probe the field; press play and watch every layer — slice, surfaces, arrows — move together. Any expression you type in x, y, z and t gets this same treatment.'}
]},
{ g:'Mechanics — a particle in a field  (AP Physics C)', items:[
  {n:'Newton’s first law: no force at all', ex:'F = 0 everywhere', mode:'vector', P:'0', Q:'0', R:'0', view:'2d',
   probe:[-2.2,-1.4,0], show:{...L0, probe:1}, dens:4, extent:3,
   part:{v:[0.9,0.6,0], run:1},
   out:'Zero field, zero force: the particle’s velocity never changes and the trail is a perfect straight line at constant speed.',
   note:'Inertia is the special case F = 0 of Newton’s second law, and the integrator honours it exactly. Watch the readout: |v|, KE, and direction all frozen. Every other demo in this group is this one plus a field.'},
  {n:'Projectile motion: the parabola', ex:'U = y (uniform gravity), launch at an angle', mode:'scalar', f:'y', view:'2d',
   probe:[-2.2,-1.8,0], show:{...L0, level:1, slice:1}, dens:4, extent:3, sliceOf:'auto',
   part:{v:[1.15,1.5,0], run:1},
   out:'F = −∇U = (0, −1), constant. Horizontal velocity never changes; vertical velocity falls linearly; the trail is the parabola every kinematics equation describes.',
   note:'The whole of AP kinematics in one trail: x(t) = x₀ + vₓt (no horizontal force), y(t) = y₀ + v<sub>y</sub> t − ½t² (constant downward force). The energy readout shows ½|v|² + y frozen while kinetic and potential trade — fastest at the bottom, slowest at the top. Relaunch with a steeper angle from the same spot and compare ranges.'},
  {n:'Kepler orbit: gravity’s ellipse', ex:'U = −1/ρ, tangential launch', mode:'scalar', f:'-1/sqrt(x^2 + y^2)', view:'2d',
   probe:[1.5,0,0], show:{...L0, level:1, slice:1}, dens:4, extent:3, sliceOf:'auto',
   part:{v:[0,0.65,0], run:1, speed:1.6},
   out:'An inverse-square attraction closes the path into an ellipse with the mass at one focus (Kepler I). L<sub>z</sub> is exactly constant — equal areas in equal times (Kepler II) — and E < 0 marks the orbit as bound.',
   note:'Watch the two conserved numbers in the particle readout do all the work: L<sub>z</sub> never moves (the force is central, so there is no torque), and E = ½|v|² − 1/ρ never moves (the force is a gradient). The planet runs fastest at perihelion, exactly as the equal-area law demands. This launch gives an ellipse from r = 0.70 to 1.5; a tangential launch at 0.8165 would make it a circle.'},
  {n:'Escape velocity: the sign of E decides', ex:'same gravity, faster launch', mode:'scalar', f:'-1/sqrt(x^2 + y^2)', view:'2d',
   probe:[1.5,0,0], show:{...L0, level:1, slice:1}, dens:4, extent:3, sliceOf:'auto',
   part:{v:[0,1.3,0], run:1, speed:1.6},
   out:'At r = 1.5 escape speed is √(2/1.5) ≈ 1.155. This launch at 1.3 has E = ½v² − 1/r > 0: unbound — the particle leaves and never comes back.',
   note:'One number, E, sorts every trajectory: E &lt; 0 ellipse, E = 0 parabola, E &gt; 0 hyperbola. Nothing else about the launch matters for the verdict. Relaunch with v = (0, 1.1, 0) — now E &lt; 0 — and the same field bends the path into a long bound ellipse instead. Escape velocity is not about outrunning gravity; it is about the energy budget.'},
  {n:'Simple harmonic motion: the spring bowl', ex:'U = ½(x² + y²)', mode:'scalar', f:'0.5x^2 + 0.5y^2', view:'2d',
   probe:[1.4,0,0], show:{...L0, level:1, slice:1}, dens:4, extent:3, sliceOf:'auto',
   part:{v:[0,0.8,0], run:1, speed:1.4},
   out:'F = −∇U = −(x, y): the restoring force is proportional to displacement, so x(t) = 1.4·cos t and y(t) = 0.8·sin t — an ellipse traced with period 2π, regardless of amplitude.',
   note:'Hooke’s law is the linear approximation of every well-behaved minimum, which is why SHM is everywhere: pendulums (small angle), molecules, buildings. The isochrony is the deep fact — relaunch faster and the path grows but the round-trip time does not. Compare with the Kepler bowl next door, where the period grows with the orbit (T² ∝ a³).'},
  {n:'Angular momentum: central vs lopsided', ex:'U = ½x² + 0.9y² — not central', mode:'scalar', f:'0.5x^2 + 0.9y^2', view:'2d',
   probe:[1.4,0,0], show:{...L0, level:1, slice:1}, dens:4, extent:3, sliceOf:'auto',
   part:{v:[0,0.9,0], run:1, speed:1.4},
   out:'The force −∇U no longer points at the origin, so it exerts torque: watch L<sub>z</sub> in the readout oscillate instead of holding still. The orbit precesses into a rosette instead of closing.',
   note:'Conservation laws are earned, not free: L is conserved exactly when the force is central (τ = r × F = 0), and E is conserved exactly when the force is a gradient. This field keeps the second and gives up the first — L<sub>z</sub> breathes while E stays frozen. Load the round bowl again and both freeze. That contrast <b>is</b> the rotational-dynamics chapter.'}
]},
{ g:'Charged particles — AP E&M in motion', items:[
  {n:'Cyclotron motion: circles from v×B', ex:'B = ẑ (uniform), q v×B', mode:'vector', P:'0', Q:'0', R:'1', view:'2d',
   probe:[0,-1,0], show:{...L0, probe:1}, dens:4, extent:3,
   part:{interp:'lorentz', v:[1,0,0], run:1, speed:1.4},
   out:'The magnetic force q v×B is always perpendicular to v: it can turn the velocity but never lengthen it. Constant speed + constant turning = a circle of radius r = mv/(qB) = 1.',
   note:'The two AP facts, both visible: the readout’s |v| and KE never move (magnetic forces do no work), and the radius obeys r = mv/qB — relaunch with v = (2, 0, 0) and the circle exactly doubles. Flip q to −1 in the panel and the particle orbits the other way. This is the geometry inside every mass spectrometer and the reason cyclotrons work at a fixed frequency.'},
  {n:'Helix: motion along B is free', ex:'B = ẑ in 3D, launch with v∥ and v⊥', mode:'vector', P:'0', Q:'0', R:'1',
   probe:[0,-1,-1.8], show:{...L0, probe:1, arrows:1}, dens:4, extent:3,
   part:{interp:'lorentz', v:[1,0,0.4], run:1, speed:1.4},
   out:'v×B ignores the component of v along B, so v∥ rides free while v⊥ circles: the path is a helix of radius mv⊥/(qB) climbing at constant v∥.',
   note:'Decompose and conquer: the perpendicular motion is the cyclotron circle, the parallel motion is Newton’s first law, and the helix is their sum. This is why charged particles spiral along magnetic field lines — the aurora is this picture drawn by the solar wind on Earth’s dipole field.'},
  {n:'Velocity selector: E against v×B', ex:'B = ẑ with uniform E = (0, 0.8, 0)', mode:'vector', P:'0', Q:'0', R:'1', view:'2d',
   probe:[-2.4,0,0], show:{...L0, probe:1}, dens:4, extent:3,
   part:{interp:'lorentz', v:[0.8,0,0], E:[0,0.8,0], run:1, speed:1.4},
   out:'For a particle moving at exactly v = E/B, the electric push qE and the magnetic push qv×B cancel: it sails through dead straight. Any other speed gets deflected.',
   note:'The crossed-field velocity selector, working live: at v = 0.8 the forces balance and the trail is a ruler line. Relaunch at v = (1.2, 0, 0) — too fast, the magnetic force wins and the path bows; at (0.5, 0, 0) the electric force wins and it bows the other way. Thomson used exactly this trick to measure e/m of the electron in 1897.'}
]},
{ g:'Quantum mechanics — wavefunctions', items:[
  {n:'Particle in a box: the Laplacian is the energy', ex:'ψ = sin(πx′/3)·sin(πy′/6) on a 6×6 box', mode:'scalar',
   f:'sin(pi(x + 3)/3) sin(pi(y + 3)/6)', view:'surf',
   probe:[-0.7,0.4,0], show:{...L0, level:1}, dens:4, extent:3,
   out:'An energy eigenstate (n = 2, m = 1). Check it with the probe: ∇²ψ / ψ = −5π²/36 ≈ −1.371, the same number at every single point — that constant IS the energy eigenvalue.',
   note:'Schrödinger’s equation for a free particle in a box reads −∇²ψ = E·ψ (suitable units): the eigenstate is precisely the shape whose Laplacian is proportional to itself everywhere. Drag the probe anywhere and divide the ∇²f readout by the f readout — always −1.371. The Laplacian panel has become an energy meter. More nodes ⇒ more curvature ⇒ higher E: edit the field to make the first sine’s 3 into a 2 and watch the ratio jump.'},
  {n:'Superposition: probability that sloshes', ex:'|ψ₁ + ψ₂ e^(−iΔEt)|², animated', mode:'scalar',
   f:'sin(pi(x+3)/6)^2 sin(pi(y+3)/6)^2 + sin(pi(x+3)/3)^2 sin(pi(y+3)/6)^2 + 2 sin(pi(x+3)/6) sin(pi(x+3)/3) sin(pi(y+3)/6)^2 cos(0.8t)', view:'surf',
   probe:[-1.4,0,0], show:{...L0, level:0}, dens:4, extent:3,
   out:'Each eigenstate alone is a standing shape — but their sum is not stationary: the cross term beats at the energy difference ΔE, and the probability lump sloshes from side to side forever.',
   note:'This surface is the exact |Ψ|² of an equal superposition of the ground and first excited states — the complex phases e^(−iEt) are invisible alone, but their <b>difference</b> shows up in the interference term 2ψ₁ψ₂cos(ΔE·t). Quantum dynamics is beat physics. This sloshing dipole is, literally, how an atom radiates during a transition, and ΔE = ħω is the photon it emits.'},
  {n:'A hydrogen orbital: 2p, for real', ex:'ψ = z·e^(−r/2)', mode:'scalar', f:'z exp(-0.5r)',
   probe:[0,0,2], show:{...L0, level:1, slice:1}, dens:4, extent:5, sliceOf:'auto', sliceAxis:0,
   out:'The real 2p_z orbital of hydrogen: two lobes of opposite sign pinched at a nodal plane. And it solves Schrödinger: probe it — ∇²ψ/ψ = ¼ − 2/r exactly, which is 2(V − E) with V = −1/r and E = −⅛.',
   note:'Not an artist’s impression — the actual function, drawn as its level surfaces and a signed colour slice (warm lobe +, cool lobe −). Check the eigen-relation anywhere: at (0, 0, 2), ∇²ψ/ψ = ¼ − 1 = −0.75; at (1, 1, 1), ¼ − 2/√3 ≈ −0.905. The ratio depends only on r, never on direction — that is the spherical symmetry of the potential talking. Chemistry’s p-orbital pictures are level sets of functions exactly like this one.'},
  {n:'Ground state & the classical turning point', ex:'ψ = e^(−r²/2), harmonic oscillator', mode:'scalar',
   f:'exp(-(x^2 + y^2)/2)', view:'2d',
   probe:[1.42,0,0], show:{...L0, level:1, slice:1}, dens:4, extent:3, sliceOf:'div',
   out:'The map is coloured by ∇²ψ — the kinetic-energy term of Schrödinger’s equation. It changes sign on the circle r = √2: inside, the state is kinetic-rich; outside, it is tunnelling into the classically forbidden region.',
   note:'For the oscillator ground state, ∇²ψ = (r² − 2)ψ: negative curvature where a classical particle would swing, positive where it could never go (V &gt; E). The colour seam in the map <b>is</b> the classical turning point, and the probability leaking past it is tunnelling — the effect behind alpha decay and scanning-tunnelling microscopes. The probe starts right on the seam: nudge it either way and watch ∇²f flip sign.'},
  {n:'Higher mode, higher energy: n = 3, m = 2', ex:'more nodes ⇒ more curvature ⇒ more E', mode:'scalar',
   f:'sin(pi(x + 3)/2) sin(pi(y + 3)/3)', view:'surf',
   probe:[-0.4,0.6,0], show:{...L0, level:1}, dens:4, extent:3,
   out:'The (3, 2) eigenstate of the same box. The eigenvalue meter now reads −13π²/36 ≈ −3.565 at every point — 2.6× the (2, 1) state, because E ∝ n² + (m/2)² grows with the node count.',
   note:'Compare with the first box demo, probing anywhere: same box, more wiggles, deeper eigenvalue. This is <b>why atoms have discrete spectra</b>: confining a wave forces whole numbers of half-wavelengths, and each extra node costs curvature, which costs energy. The steps between these levels are the photons of atomic spectra. The ∇²f ⁄ f row in the probe panel is computed live — drag anywhere and it holds.'},
  {n:'The delta well: one bound state', ex:'ψ = e^(−|x|), the energy well distilled', mode:'scalar',
   f:'exp(-abs(x))', view:'surf',
   probe:[0.8,0.5,0], show:{...L0, level:1}, dens:4, extent:3,
   out:'The exact bound state of a point-like well: a tent of probability pinched at x = 0, decaying both ways. Off the ridge, the eigenvalue meter reads +1 everywhere: ψ″ = ψ, i.e. E = −½.',
   note:'A particle <b>bound</b> in a well has negative energy, and everywhere outside the well it lives in the classically forbidden region — that is why ∇²ψ/ψ is <i>positive</i> here: pure decay, pure tunnelling. One honest subtlety: the symbolic Laplacian is blind to the kink at x = 0, and the missing −2δ(x) spike <b>is</b> the well itself — all of the attraction lives in that single crease. Finite square wells round the crease off and can hold several such states.'},
  {n:'Heisenberg: squeeze x, pay in p', ex:'ψ = e^(−r²/4σ²) with σ = 0.4', mode:'scalar',
   f:'exp(-(x^2 + y^2)/0.64)', view:'surf',
   probe:[0,0,0], show:{...L0, level:1}, dens:4, extent:3,
   out:'A packet confined to Δx ≈ 0.4. The eigenvalue meter at the peak reads ∇²ψ/ψ = −4/σ² ≈ −6.25 — and curvature is kinetic energy, so ⟨p²⟩ ∝ 1/σ². Δx·Δp cannot be beaten down.',
   note:'The uncertainty principle, made mechanical: to localise a wave you must bend it sharply, and −∇²ψ <b>is</b> the kinetic term of Schrödinger’s equation. Now edit the field: change 0.64 to 4 (σ = 1). The packet spreads out, and the meter at the origin relaxes from −6.25 to −1 — exactly 1/σ². Squeeze position by k, pay k² in momentum spread: Δx·Δp ≥ ħ/2 is this trade-off’s floor. It is why atoms don’t collapse: pinning the electron at the nucleus would cost infinite kinetic energy.'},
  {n:'Blackbody radiation: Planck’s ridge', ex:'u(ν, T) as terrain — x is frequency, y is temperature', mode:'scalar',
   f:'(x + 3.2)^3/(exp((x + 3.2)/(0.35(y + 3.5))) - 1)', view:'surf',
   probe:[0.25,0,0], show:{...L0, level:1}, dens:4, extent:3,
   out:'Planck’s law drawn over parameter space: at each temperature (y), the spectrum over frequency (x) rises as ν³ then is chopped by the e^(ν/T) − 1 quantum cutoff. The crest line drifting to higher ν as T grows is Wien’s displacement law.',
   note:'The axes are not space — they are frequency and temperature, exactly like the regression demo’s parameter plane. Walk the probe along constant y: that is one temperature’s spectrum, peaking where ∂u/∂ν = 0 (the ridge, ν ≈ 2.82T). Now type the classical guess instead: <span style="font-family:var(--f-mono)">(x+3.2)^2 (y+3.5)</span> — Rayleigh–Jeans — and the surface just climbs forever: the ultraviolet catastrophe. Planck’s quantised oscillators, the −1 in that denominator, are what fold the surface back down. This 1900 fit is where quantum mechanics began.'},
  {n:'Interference is the qubit’s resource', ex:'two coherent sources, relative phase 2.0 rad', mode:'scalar', view:'2d',
   phys:[{type:'antenna', A:1, k:4, phi:0, pos:{x:0,y:0.8}}, {type:'antenna', A:1, k:4, phi:2.0, pos:{x:0,y:-0.8}}],
   probe:[1.8,0,0], show:{...L0, slice:1}, dens:4, extent:3, sliceOf:'auto',
   out:'Two coherent sources with a 2.0 rad phase offset: the interference fringes shift off the midline, because where waves reinforce is set by phase, not geometry alone.',
   note:'This double-slit pattern is quantum computing’s working capital. A qubit is a superposition with a <b>phase</b>; gates rotate that phase; and the final measurement is an interference pattern in which wrong answers cancel and right answers add — precisely how the fringes here move when you edit φ in the Physics builder (try 0, then π). An N-qubit register is a superposition over 2^N such amplitudes; algorithms like Grover’s and Shor’s are choreography that steers the big fringes onto the answer. Decoherence is what happens when the environment scrambles φ — the fringes wash out, and with them the advantage.'}
]}];
